import java.math.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;

enum EventType { PRICE_CHANGED, PRICE_DROPPED, STOCK_CHANGED, LOW_STOCK, CATEGORY_ANALYZED, MARKETPLACE_SUMMARY }
record PriceEvent(String productId, BigDecimal previousPrice, BigDecimal newPrice, String categoryId, EventType type, long sequence) {}
record StockEvent(String productId, int previousQuantity, int newQuantity, String categoryId, EventType type, long sequence) {}
record SummaryEvent(long priceEvents, long stockEvents, long sequence) {}
record CategoryReport(String categoryId, int products, BigDecimal tax, BigDecimal shipping) {}

interface Observer<T> { void onEvent(T event); }
interface Subject<T> { void subscribe(EventType type, Observer<T> observer); void unsubscribe(EventType type, Observer<T> observer); void publish(T event, EventType type); }

class EventSubject<T> implements Subject<T> {
  private final ConcurrentHashMap<EventType, CopyOnWriteArrayList<Observer<T>>> listeners = new ConcurrentHashMap<>();
  public void subscribe(EventType type, Observer<T> observer) { listeners.computeIfAbsent(type, k -> new CopyOnWriteArrayList<>()).addIfAbsent(observer); }
  public void unsubscribe(EventType type, Observer<T> observer) { var list=listeners.get(type); if(list!=null) list.remove(observer); }
  public void publish(T event, EventType type) { var snapshot=listeners.getOrDefault(type,new CopyOnWriteArrayList<>()); for(var o:snapshot) try{o.onEvent(event);}catch(RuntimeException ex){System.err.println("Listener failed: "+ex.getMessage());} }
  public int listenerCount(){return listeners.values().stream().mapToInt(List::size).sum();}
}
class PriceUpdateSource extends EventSubject<PriceEvent> { private final AtomicLong seq=new AtomicLong(); public void update(String id, BigDecimal oldP, BigDecimal newP, String cat){var t=newP.compareTo(oldP)<0?EventType.PRICE_DROPPED:EventType.PRICE_CHANGED; publish(new PriceEvent(id,oldP,newP,cat,t,seq.incrementAndGet()),t); if(t==EventType.PRICE_DROPPED) publish(new PriceEvent(id,oldP,newP,cat,t,seq.get()),EventType.PRICE_CHANGED); } }
class StockUpdateSource extends EventSubject<StockEvent> { private final AtomicLong seq=new AtomicLong(); public void update(String id,int oldQ,int newQ,String cat){var e=new StockEvent(id,oldQ,newQ,cat,newQ==0||newQ<5?EventType.LOW_STOCK:EventType.STOCK_CHANGED,seq.incrementAndGet()); publish(e,e.type()); publish(e,EventType.STOCK_CHANGED); } }

interface CatalogVisitor<R>{R visit(MarketplaceCatalog e); R visit(ProductCategory e); R visit(PhysicalProduct e); R visit(DigitalProduct e); R visit(ServiceProduct e); R visit(SubscriptionProduct e); R visit(GiftCardProduct e);}
interface CatalogElement { <R> R accept(CatalogVisitor<R> visitor); String id(); String name(); }
abstract class CatalogContainer implements CatalogElement { protected final String id,name; protected final List<CatalogElement> children=new ArrayList<>(); CatalogContainer(String id,String name){this.id=id;this.name=name;} public String id(){return id;} public String name(){return name;} public void add(CatalogElement e){children.add(e);} public List<CatalogElement> children(){return List.copyOf(children);} }
class MarketplaceCatalog extends CatalogContainer { MarketplaceCatalog(String id,String name){super(id,name);} public <R> R accept(CatalogVisitor<R> v){return v.visit(this);} }
class ProductCategory extends CatalogContainer { ProductCategory(String id,String name){super(id,name);} public <R> R accept(CatalogVisitor<R> v){return v.visit(this);} }
abstract class Product implements CatalogElement { final String id,name,categoryId; final BigDecimal price; final boolean available; Product(String i,String n,String c,BigDecimal p,boolean a){id=i;name=n;categoryId=c;price=p;available=a;} public String id(){return id;} public String name(){return name;} }
class PhysicalProduct extends Product { final BigDecimal weight; PhysicalProduct(String i,String n,String c,BigDecimal p,boolean a,BigDecimal w){super(i,n,c,p,a);weight=w;} public <R> R accept(CatalogVisitor<R> v){return v.visit(this);} }
class DigitalProduct extends Product { DigitalProduct(String i,String n,String c,BigDecimal p,boolean a){super(i,n,c,p,a);} public <R> R accept(CatalogVisitor<R> v){return v.visit(this);} }
class ServiceProduct extends Product { ServiceProduct(String i,String n,String c,BigDecimal p,boolean a){super(i,n,c,p,a);} public <R> R accept(CatalogVisitor<R> v){return v.visit(this);} }
class SubscriptionProduct extends Product { SubscriptionProduct(String i,String n,String c,BigDecimal p,boolean a){super(i,n,c,p,a);} public <R> R accept(CatalogVisitor<R> v){return v.visit(this);} }

abstract class TraversingVisitor<R> implements CatalogVisitor<R>{ protected void each(CatalogContainer c){for(var x:c.children())x.accept(this);} public R visit(MarketplaceCatalog e){each(e);return result();} public R visit(ProductCategory e){each(e);return result();} protected abstract R result(); }
class TaxCalculationVisitor extends TraversingVisitor<BigDecimal>{private BigDecimal total=BigDecimal.ZERO; protected BigDecimal result(){return total;} private BigDecimal tax(Product p,BigDecimal rate){total=total.add(p.price.multiply(rate));return total;} public BigDecimal visit(PhysicalProduct e){return tax(e, new BigDecimal("0.12"));} public BigDecimal visit(DigitalProduct e){return tax(e,new BigDecimal("0.20"));} public BigDecimal visit(ServiceProduct e){return tax(e,new BigDecimal("0.15"));} public BigDecimal visit(SubscriptionProduct e){return tax(e,new BigDecimal("0.10"));} public BigDecimal visit(GiftCardProduct e){return tax(e,BigDecimal.ZERO);}}
record CatalogStats(int products,int physical,int digital,int services,int subscriptions,BigDecimal value){}
class CatalogStatisticsVisitor extends TraversingVisitor<CatalogStats>{int n,ph,di,se,su; BigDecimal value=BigDecimal.ZERO; protected CatalogStats result(){return new CatalogStats(n,ph,di,se,su,value);} private void add(Product p){n++;value=value.add(p.price);} public CatalogStats visit(PhysicalProduct e){ph++;add(e);return result();}public CatalogStats visit(DigitalProduct e){di++;add(e);return result();}public CatalogStats visit(ServiceProduct e){se++;add(e);return result();}public CatalogStats visit(SubscriptionProduct e){su++;add(e);return result();} public CatalogStats visit(GiftCardProduct e){add(e);return result();}}
class ProductFilterVisitor extends TraversingVisitor<List<Product>>{private final Predicate<Product> test; private final List<Product> found=new ArrayList<>(); ProductFilterVisitor(Predicate<Product> t){test=t;} protected List<Product> result(){return List.copyOf(found);} private List<Product> add(Product p){if(test.test(p))found.add(p);return result();}public List<Product> visit(PhysicalProduct e){return add(e);}public List<Product> visit(DigitalProduct e){return add(e);}public List<Product> visit(ServiceProduct e){return add(e);}public List<Product> visit(SubscriptionProduct e){return add(e);} public List<Product> visit(GiftCardProduct e){return add(e);}}
class ShippingCostVisitor extends TraversingVisitor<BigDecimal>{BigDecimal total=BigDecimal.ZERO;protected BigDecimal result(){return total;}private BigDecimal add(BigDecimal n){total=total.add(n);return total;}public BigDecimal visit(PhysicalProduct e){return add(e.weight.multiply(new BigDecimal("2.50")));}public BigDecimal visit(DigitalProduct e){return add(BigDecimal.ZERO);}public BigDecimal visit(ServiceProduct e){return add(new BigDecimal("5.00"));}public BigDecimal visit(SubscriptionProduct e){return add(new BigDecimal("1.00"));} public BigDecimal visit(GiftCardProduct e){return add(BigDecimal.ZERO);}}
class XmlExportVisitor extends TraversingVisitor<String>{private final StringBuilder b=new StringBuilder();protected String result(){return b.toString();}private String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}private void open(CatalogContainer e){b.append("<").append(e.getClass().getSimpleName()).append(" id=\"").append(esc(e.id())).append("\" name=\"").append(esc(e.name())).append("\">");}private void close(CatalogContainer e){b.append("</").append(e.getClass().getSimpleName()).append(">");}public String visit(MarketplaceCatalog e){open(e);each(e);close(e);return result();}public String visit(ProductCategory e){open(e);each(e);close(e);return result();}private String product(Product p,String type){b.append("<").append(type).append(" id=\"").append(esc(p.id())).append("\" name=\"").append(esc(p.name())).append("\" price=\"").append(p.price).append("\"/>");return result();}public String visit(PhysicalProduct e){return product(e,"PhysicalProduct");}public String visit(DigitalProduct e){return product(e,"DigitalProduct");}public String visit(ServiceProduct e){return product(e,"ServiceProduct");}public String visit(SubscriptionProduct e){return product(e,"SubscriptionProduct");} public String visit(GiftCardProduct e){return product(e,"GiftCardProduct");}}

class MarketplaceAggregator implements Observer<PriceEvent>, Subject<SummaryEvent>{private final EventSubject<SummaryEvent> out=new EventSubject<>();private final AtomicLong prices=new AtomicLong(),stocks=new AtomicLong();public void onEvent(PriceEvent e){prices.incrementAndGet();republish();}public void onStockEvent(StockEvent e){stocks.incrementAndGet();republish();}private void republish(){out.publish(new SummaryEvent(prices.get(),stocks.get(),prices.get()+stocks.get()),EventType.MARKETPLACE_SUMMARY);}public void subscribe(EventType t,Observer<SummaryEvent> o){out.subscribe(t,o);}public void unsubscribe(EventType t,Observer<SummaryEvent> o){out.unsubscribe(t,o);}public void publish(SummaryEvent e,EventType t){out.publish(e,t);}}
class MarketplaceInspectionService implements Observer<StockEvent>{private final Map<String,ProductCategory> categories;private final List<CategoryReport> reports=new CopyOnWriteArrayList<>();MarketplaceInspectionService(Map<String,ProductCategory> c){categories=c;}public void onEvent(StockEvent e){if(e.type()!=EventType.LOW_STOCK)return;var c=categories.get(e.categoryId());if(c!=null){var tax=c.accept(new TaxCalculationVisitor());var ship=c.accept(new ShippingCostVisitor());reports.add(new CategoryReport(c.id(),c.accept(new CatalogStatisticsVisitor()).products(),tax,ship));}}public List<CategoryReport> reports(){return List.copyOf(reports);}}
